def format_success_rate(numerator: int, denominator: int) -> str:
    if isinstance(numerator, bool) or isinstance(denominator, bool):
        raise ValueError("Bools are not valid integers for this operation.")
    if not isinstance(numerator, int) or not isinstance(denominator, int):
        raise ValueError("numerator and denominator must be integers.")
    if denominator <= 0:
        raise ValueError("denominator must be a positive integer.")
    if numerator < 0 or numerator > denominator:
        raise ValueError("numerator must be in [0, denominator].")

    from decimal import Decimal, ROUND_HALF_EVEN

    rate = Decimal(numerator) / Decimal(denominator) * 100
    formatted = rate.quantize(Decimal('0.1'), rounding=ROUND_HALF_EVEN)

    return f"{formatted}%"
